    "howToApply": {
      "mr": [
        "१) महाडीबीटी (MahaDBT) शेतकरी योजनेच्या अधिकृत पोर्टलला (mahadbt.maharashtra.gov.in) भेट द्या.",
        "२) 'नवीन अर्जदार नोंदणी' वर क्लिक करून युझर आयडी व पासवर्ड तयार करा किंवा आधार क्रमांकाने लॉगिन करा.",
        "३) 'वैयक्तिक माहिती' व 'शेतजमिनीचा तपशील' (७/१२ व ८-अ उतारा क्रमांक) अचूक भरा.",
        "४) 'कृषी योजना' विभागात जाऊन संबंधित योजनेची व घटकाची निवड करा.",
        "५) आवश्यक कागदपत्रे (७/१२, ८-अ, आधार कार्ड, बँक पासबुक) स्कॅन करून अपलोड करा.",
        "६) अर्ज शुल्क भरून फॉर्म सबमिट करा आणि मिळणाऱ्या पोचपावतीची (Receipt) प्रिंट सुरक्षित ठेवा.",
        "७) तालुका कृषी अधिकारी / मंडळ कृषी अधिकारी यांच्याकडून पूर्वसंमती (Pre-sanction) पत्र मिळताच शेतात काम सुरू करा किंवा अधिकृत विक्रेत्याकडून साहित्य खरेदी करा.",
        "८) काम पूर्ण झाल्यावर किंवा साहित्य खरेदी केल्यावर मूळ देयक (GST Invoice) पोर्टलावर अपलोड करा.",
        "९) कृषी सहायकाकडून प्रत्यक्ष स्थळ पाहणी (Physical Verification) व जिओ-टॅगिंग पूर्ण झाल्यावर अनुदानाची रक्कम थेट बँक खात्यात (DBT) जमा केली जाईल."
      ],
      "en": [
        "1) Visit the official MahaDBT Farmer Portal (mahadbt.maharashtra.gov.in).",
        "2) Click on 'New Applicant Registration' to create User ID & Password or login using Aadhaar Number.",
        "3) Fill in Personal Details and Land Holding details (7/12 & 8-A extract survey numbers) accurately.",
        "4) Navigate to 'Agriculture Schemes' section and select the required scheme component.",
        "5) Scan and upload all required documents (7/12 extract, 8-A extract, Aadhaar Card, Bank Passbook).",
        "6) Pay the nominal application fee, submit the form, and print/save the application acknowledgment receipt.",
        "7) After receiving the Pre-sanction Approval Letter from Taluka/Circle Agriculture Officer, purchase equipment from authorized dealers or commence field work.",
        "8) Upload original purchase tax invoice (GST Bill) on the portal within 30 days of pre-approval.",
        "9) After physical field inspection and Geo-tagging by Agriculture Assistant, the subsidy will be directly credited to your bank account via DBT."
      ],
      "hi": [
        "1) आधिकारिक महाडीबीटी किसान पोर्टल (mahadbt.maharashtra.gov.in) पर जाएं।",
        "2) 'नया आवेदक पंजीकरण' पर क्लिक करके यूजर आईडी और पासवर्ड बनाएं अथवा आधार नंबर से लॉगिन करें।",
        "3) व्यक्तिगत विवरण और कृषि भूमि विवरण (7/12 और 8-अ नकल) सही-सही भरें।",
        "4) 'कृषि योजनाएं' अनुभाग में जाकर संबंधित योजना और घटक का चयन करें।",
        "5) आवश्यक दस्तावेज (7/12, 8-अ, आधार कार्ड, बैंक पासबुक) स्कैन करके अपलोड करें।",
        "6) आवेदन शुल्क का भुगतान कर फॉर्म सबमिट करें और पावती रसीद की प्रिंट कॉपी सुरक्षित रखें।",
        "7) तालुका कृषि अधिकारी से पूर्व-स्वीकृति (Pre-sanction) पत्र मिलने के बाद ही अधिकृत डीलर से सामग्री खरीदें या कार्य शुरू करें।",
        "8) कार्य पूर्ण होने या सामग्री खरीदने के 30 दिनों के भीतर मूल जीएसटी बिल पोर्टल पर अपलोड करें।",
        "9) कृषि सहायक द्वारा भौतिक सत्यापन एवं जियो-टैगिंग के बाद सब्सिडी राशि सीधे आपके बैंक खाते (DBT) में जमा कर दी जाएगी।"
      ],
      "ahr": [
        "१) महाडीबीटी (MahaDBT) पोर्टलवर (mahadbt.maharashtra.gov.in) जावा.",
        "२) नवीन नोंदणी करा किंवा आधार नंबरनं लॉगिन करा.",
        "३) आपली माहिती अन जमिनीचा ७/१२, ८-अ उतारा भरा.",
        "४) योजना निवडा अन कागदपत्रे (७/१२, आधार कार्ड, बँक पासबुक) अपलोड करा.",
        "५) फॉर्म सबमिट करून पावती प्रिंट काढून ठेवा.",
        "६) पूर्व-मंजुरी पत्र मिळनावर खरेदी करा अन बिल अपलोड करा.",
        "७) तपासणी झाल्यावर पैसे थेट बँक खात्यात जमा होतील."
      ],
      "kok": [
        "१) महाडीबीटी पोर्टलार (mahadbt.maharashtra.gov.in) वचात.",
        "२) नवी नोंदणी करात वा आधार नंबरान लॉगिन करात.",
        "३) तुमची म्हायती आनी ७/१२, ८-अ दाखलो भरात.",
        "४) योजना विंचून कागदपत्रां अपलोड करात.",
        "५) फॉर्म सबमिट करून पावती दवरात.",
        "६) पूर्व-मंजुरी मेळटकीच खरेदी करात आनी बील अपलोड करात.",
        "७) तपासणी जाल्या उपरांत अनुदान बँक खात्यांत जमा जातलें."
      ]
    }
